/// Read a cookie from one or more forwarded `cookie` header values.
///
/// FIRST match wins. On a request carrying
/// `session=shadow; session=real` this answers `shadow`; an application that
/// must not accept a shadowed cookie checks for the duplicate itself. Note
/// also that upstream's gateway forwards only the first of a repeated request
/// header (ledger 10, row R9), so a second `cookie` header never arrives.
pub fn cookie_value<'a>(headers: &'a [(String, String)], name: &str) -> Option<&'a str> {
    headers
        .iter()
        .filter(|(header, _)| header.eq_ignore_ascii_case("cookie"))
        .flat_map(|(_, value)| value.split(';'))
        .filter_map(|part| part.trim().split_once('='))
        .find_map(|(key, value)| (key == name).then_some(value))
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn secure_session_cookie_and_exact_parser() {
        let rendered = ResponseCookie::session("ferrite_session", "abc_123")
            .unwrap()
            .max_age_secs(3600)
            .render()
            .unwrap();
        assert_eq!(
            rendered,
            "ferrite_session=abc_123; Path=/; Max-Age=3600; HttpOnly; Secure; SameSite=Strict"
        );
        assert!(!rendered.contains("Domain="));
        assert!(ResponseCookie::session("bad\r\nname", "x").is_err());
        let headers = vec![("cookie".into(), "other=1; ferrite_session=abc".into())];
        assert_eq!(cookie_value(&headers, "ferrite_session"), Some("abc"));
        // First match wins, as on the platform. The shadow is what the
        // application sees, here and on the fleet alike.
        let duplicated = vec![(
            "cookie".into(),
            "ferrite_session=shadow; ferrite_session=real".into(),
        )];
        assert_eq!(cookie_value(&duplicated, "ferrite_session"), Some("shadow"));
    }

    /// A `__Host-` name is an ordinary cookie name to this crate, exactly as
    /// it is to the platform crate. The prefix's three conditions are the
    /// business of `super::host_session` and `super::render`, which compose
    /// them and re-check them on the rendered header; mirroring a stricter
    /// `validate` here would refuse locally what the fleet accepts.
    #[test]
    fn a_host_prefixed_name_gets_no_local_only_rule() {
        let widened = ResponseCookie::session("__Host-session", "opaque")
            .unwrap()
            .path("/admin")
            .unwrap();
        assert_eq!(
            widened.render().unwrap(),
            "__Host-session=opaque; Path=/admin; HttpOnly; Secure; SameSite=Strict"
        );
    }
}
